```hcl
# Example: enable Automatic Restart for a Compute Engine VM instance
resource "google_compute_instance" "example" {
  name         = var.instance_name
  machine_type = var.machine_type
  zone         = var.zone

  scheduling {
    automatic_restart   = true
    on_host_maintenance = "MIGRATE"
  }
}
```

```hcl
resource "google_compute_instance" "vm" {
  name         = "<example_resource_name>"
  zone         = "<ZONE>"
  machine_type = "e2-micro"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
    }
  }

  network_interface {
    network = "default"
  }

  metadata = {
    block-project-ssh-keys = "true" # Critical: blocks project-wide SSH keys for this VM
  }
}
```

```hcl
resource "google_compute_instance" "<example_resource_name>" {
  name         = "<example_resource_name>"
  machine_type = "n2d-standard-2"  # Supported for Confidential VM
  zone         = "<ZONE>"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
    }
  }

  network_interface {}

  # Critical: Enables Confidential Computing on the VM
  confidential_instance_config {
    enable_confidential_compute = true  # Turns on Confidential VM
  }
}
```

```hcl
# Create a non-default service account
resource "google_service_account" "<example_resource_name>" {
  account_id = "<example_resource_id>"  # CRITICAL: custom SA to avoid default "-compute@developer.gserviceaccount.com"
}

# Attach the non-default service account to the VM
resource "google_compute_instance" "<example_resource_name>" {
  name         = "<example_resource_name>"
  machine_type = "e2-micro"
  zone         = "<ZONE>"

  boot_disk { initialize_params { image = "debian-cloud/debian-12" } }
  network_interface { network = "default" }

  service_account {
    email = google_service_account.<example_resource_name>.email  # CRITICAL: use non-default SA so the check passes
  }
}
```

```hcl
resource "google_compute_instance" "<example_resource_name>" {
  name         = "<example_resource_name>"
  machine_type = "e2-micro"
  zone         = "us-central1-a"

  boot_disk { initialize_params { image = "debian-cloud/debian-12" } }
  network_interface { network = "default" }

  service_account {
    email  = "<example_service_account_email>" # FIX: use a non-default service account to avoid the default SA
    scopes = ["https://www.googleapis.com/auth/devstorage.read_only"] # FIX: avoid cloud-platform (full API access)
  }
}
```

```hcl
