```hcl
resource "google_compute_instance" "example_resource" {
  name         = "example-instance"
  machine_type = "e2-medium"
  zone         = "us-central1-a"

  boot_disk {
    # Disable auto-delete for the boot disk
    auto_delete = false

    initialize_params {
      image = "debian-cloud/debian-11"
    }
  }

  attached_disk {
    source      = google_compute_disk.example_disk.id
    # Disable auto-delete for attached disks
    auto_delete = false
  }

  network_interface {
    network = "default"
  }
}
```

```hcl
resource "google_compute_instance" "<example_resource_name>" {
  name         = "<example_resource_name>"
  machine_type = "e2-medium"
  zone         = "<example_zone>"

  boot_disk {
    initialize_params { image = "debian-cloud/debian-12" }
    # Critical: enables Customer-Supplied Encryption Key (CSEK) for the boot disk
    disk_encryption_key { raw_key = "<BASE64_32BYTE_KEY>" }  # base64-encoded AES-256 key
