```hcl
# Example: configure On Host Maintenance to MIGRATE for a Compute Engine VM instance
resource "google_compute_instance" "example" {
  name         = var.instance_name
  machine_type = var.machine_type
  zone         = var.zone

  scheduling {
    # Live migrate during host maintenance events
    on_host_maintenance = "MIGRATE"
  }
}
```

```hcl
