```hcl
# To remediate, either delete the suspended instance or resume it
# Delete by removing the resource from your Terraform configuration
# Or resume by changing the desired_status
resource "google_compute_instance" "example_resource" {
  name         = "example-instance"
  machine_type = "e2-medium"
  zone         = "us-central1-a"

  # Set desired_status to RUNNING to resume the instance
  desired_status = "RUNNING"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
    }
  }

  network_interface {
    network = "default"
  }
}
```

