```hcl
resource "google_logging_metric" "metric" {
  name   = "<example_resource_name>"
  # Critical: this filter captures audit config changes via SetIamPolicy
  filter = "protoPayload.methodName=\"SetIamPolicy\" AND protoPayload.serviceData.policyDelta.auditConfigDeltas:*"
}

resource "google_monitoring_alert_policy" "alert" {
  display_name = "<example_resource_name>"
  combiner     = "OR"

  conditions {
    display_name = "<example_resource_name>"
    condition_threshold {
      # Critical: associates the alert with the log-based metric created above
      filter          = "metric.type=\"logging.googleapis.com/user/<example_resource_name>\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "60s"
    }
  }
}
```

```hcl
# Create a logs-based metric for GCS IAM permission changes
resource "google_logging_metric" "<example_resource_name>" {
  name   = "<example_resource_name>"
  filter = "resource.type=\"gcs_bucket\" AND protoPayload.methodName=\"storage.setIamPermissions\"" # CRITICAL: matches required filter for detection
}

# Alert policy referencing the above metric
resource "google_monitoring_alert_policy" "<example_resource_name>" {
  display_name = "<example_resource_name>"
  combiner     = "OR"
  conditions {
    display_name = "<example_resource_name>"
    condition_threshold {
      filter          = "metric.type=\"logging.googleapis.com/user/${google_logging_metric.<example_resource_name>.name}\"" # CRITICAL: ties alert to the metric so check passes
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "0s"
    }
  }
}
```

```hcl
resource "google_logging_metric" "compute_config_changes" {
  name   = "compute_config_changes"
  filter = "protoPayload.serviceName=\"compute.googleapis.com\""
  metric_descriptor {
    metric_kind = "DELTA"
    value_type  = "INT64"
  }
}

resource "google_monitoring_alert_policy" "compute_config_alert" {
  display_name = "Compute Engine Configuration Changes"
  conditions {
    display_name = "Compute config changes detected"
    condition_threshold {
      filter          = "metric.type=\"logging.googleapis.com/user/compute_config_changes\""
      duration        = "0s"
      comparison      = "COMPARISON_GT"
      threshold_value = 0
    }
  }
  notification_channels = [var.notification_channel_id]
}
```

```hcl
resource "google_logging_metric" "<example_resource_name>" {
  name = "<example_resource_name>"
  # Critical: log-based metric for IAM custom role create/update/delete
  filter = "resource.type=\"iam_role\" AND (protoPayload.methodName=\"google.iam.admin.v1.CreateRole\" OR protoPayload.methodName=\"google.iam.admin.v1.DeleteRole\" OR protoPayload.methodName=\"google.iam.admin.v1.UpdateRole\")"
}

resource "google_monitoring_alert_policy" "<example_resource_name>" {
  display_name = "<example_resource_name>"
  conditions {
    condition_threshold {
      # Critical: alert policy targets the user log-based metric by name
      filter          = "metric.type=\"logging.googleapis.com/user/<example_resource_name>\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "0s"
    }
  }
}
```

```hcl
resource "google_logging_metric" "<example_resource_name>" {
  name = "<example_resource_name>"
  # CRITICAL: Detects project ownership assignments/changes
  filter = <<-EOT
(protoPayload.serviceName="cloudresourcemanager.googleapis.com") AND (ProjectOwnership OR projectOwnerInvitee) OR (protoPayload.serviceData.policyDelta.bindingDeltas.action="REMOVE" AND protoPayload.serviceData.policyDelta.bindingDeltas.role="roles/owner") OR (protoPayload.serviceData.policyDelta.bindingDeltas.action="ADD" AND protoPayload.serviceData.policyDelta.bindingDeltas.role="roles/owner")
EOT
}

resource "google_monitoring_alert_policy" "<example_resource_name>" {
  display_name = "<example_resource_name>"
  combiner     = "OR"

  conditions {
    condition_threshold {
      # CRITICAL: References the log-based metric so an alert is associated with it
      filter          = "metric.type=\"logging.googleapis.com/user/${google_logging_metric.<example_resource_name>.name}\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "0s"
    }
  }
}
```

